// Login.js
import React, { useState } from "react";
import { getAuth, signInWithEmailAndPassword, createUserWithEmailAndPassword, signInWithPopup, GoogleAuthProvider } from "firebase/auth";

import { signInWithGoogle, logOut } from "./firebaseConfig";

const Login = () => {
  const [user, setUser] = useState(null);

  const handleLogin = async () => {
    const loggedInUser = await signInWithGoogle();
    setUser(loggedInUser);
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white p-6 rounded-lg shadow-md text-center">
        <h1 className="text-2xl font-semibold mb-4">Login / Sign Up</h1>
        
        {user ? (
          <div>
            <p className="mb-2">Welcome, {user.displayName}</p>
            <img src={user.photoURL} alt="Profile" className="rounded-full w-16 h-16 mx-auto mb-2" />
            <button
              onClick={() => {
                logOut();
                setUser(null);
              }}
              className="bg-red-500 text-white px-4 py-2 rounded mt-2"
            >
              Logout
            </button>
          </div>
        ) : (
          <button
            onClick={handleLogin}
            className="bg-blue-500 text-white px-4 py-2 rounded"
          >
            Sign In with Google
          </button>
        )}
      </div>
    </div>
  );
};

export default Login;
